package br.com.sergio.gestaopedidos.repository;import br.com.sergio.gestaopedidos.entity.MovimentacaoEstoque;import br.com.sergio.gestaopedidos.enums.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.LocalDateTime;import java.util.*;
public interface MovimentacaoEstoqueRepository extends JpaRepository<MovimentacaoEstoque,Long>{boolean existsByItemCompraIdAndTipo(Long itemId,TipoMovimentacaoEstoque tipo);
 @EntityGraph(attributePaths={"insumo","produto","itemCompra","itemCompra.compra"})@Query("SELECT m FROM MovimentacaoEstoque m WHERE (:inicio IS NULL OR m.dataMovimentacao>=:inicio) AND (:fim IS NULL OR m.dataMovimentacao<=:fim) AND (:categoria IS NULL OR m.tipoItem=:categoria) AND (:referenciaId IS NULL OR m.insumo.id=:referenciaId OR m.produto.id=:referenciaId) AND (:tipo IS NULL OR m.tipo=:tipo) AND (:compraId IS NULL OR m.itemCompra.compra.id=:compraId)")Page<MovimentacaoEstoque> listar(@Param("inicio")LocalDateTime inicio,@Param("fim")LocalDateTime fim,@Param("categoria")TipoItemEstoque categoria,@Param("referenciaId")Long referenciaId,@Param("tipo")TipoMovimentacaoEstoque tipo,@Param("compraId")Long compraId,Pageable pageable);
 @EntityGraph(attributePaths={"insumo","produto","itemCompra","itemCompra.compra"})@Query("SELECT m FROM MovimentacaoEstoque m WHERE m.tipoItem=:tipo AND ((:tipo=br.com.sergio.gestaopedidos.enums.TipoItemEstoque.INSUMO AND m.insumo.id=:id) OR (:tipo<>br.com.sergio.gestaopedidos.enums.TipoItemEstoque.INSUMO AND m.produto.id=:id)) ORDER BY m.dataMovimentacao DESC,m.id DESC")List<MovimentacaoEstoque> ultimas(@Param("tipo")TipoItemEstoque tipo,@Param("id")Long id,Pageable pageable);
 @EntityGraph(attributePaths={"insumo","produto","itemCompra"})List<MovimentacaoEstoque> findByItemCompraCompraIdAndTipoOrderByIdAsc(Long compraId,TipoMovimentacaoEstoque tipo);
 @EntityGraph(attributePaths={"insumo","produto","producao"})List<MovimentacaoEstoque> findByProducaoIdOrderByIdAsc(Long producaoId);
}
